package jed

// The Go deterministic-simulation runner (spec/design/simulation-testing.md). It executes `.sim`
// traces generated by scripts/sim_gen.rb against a Database over the simulated disk
// (sim_disk_test.go), checks the oracles of §8, and writes a transcript the driver
// (scripts/sim.rb) compares across cores.
//
// Run it through the driver (`mise run sim:sweep`, `mise run sim:replay`). Directly:
//
//	JED_SIM_IN=trace.sim JED_SIM_OUT=out/ go test -run '^TestSimRunner$' -count=1 .
//
// JED_SIM_IN is one .sim file, a directory of them, or a file listing trace paths one per line.
// Results append to JED_SIM_RESULTS (default JED_SIM_OUT/go.results.jsonl). With JED_SIM_IMAGES
// set, every image a recovery opens is written to JED_SIM_OUT/<trace>.go.step<N>.img for the
// independent checker (spec/fileformat/verify.rb --check-image).
// Without JED_SIM_IN the test skips, so `go test ./...` is unaffected.

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"hash/fnv"
	"os"
	"path/filepath"
	"runtime/debug"
	"sort"
	"strconv"
	"strings"
	"testing"
)

const (
	simSectorDefault = 64
	simDiskPath      = "sim.jed" // marks the engine durable; the simulated disk is its only storage
)

func TestSimRunner(t *testing.T) {
	in := os.Getenv("JED_SIM_IN")
	if in == "" {
		t.Skip("JED_SIM_IN not set (run through scripts/sim.rb)")
	}
	out := os.Getenv("JED_SIM_OUT")
	if out == "" {
		out = t.TempDir()
	}
	if err := os.MkdirAll(out, 0o755); err != nil {
		t.Fatal(err)
	}
	paths, err := simTracePaths(in)
	if err != nil {
		t.Fatal(err)
	}
	resultsPath := os.Getenv("JED_SIM_RESULTS")
	if resultsPath == "" {
		resultsPath = filepath.Join(out, "go.results.jsonl")
	}
	results, err := os.OpenFile(resultsPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	defer results.Close()
	for _, path := range paths {
		res := simRunFile(path, out)
		fmt.Fprintln(results, res.json())
		if res.violation != "" {
			t.Errorf("%s: %s", path, res.violation)
		}
	}
}

func simTracePaths(in string) ([]string, error) {
	info, err := os.Stat(in)
	if err != nil {
		return nil, err
	}
	if info.IsDir() {
		paths, err := filepath.Glob(filepath.Join(in, "*.sim"))
		sort.Strings(paths)
		return paths, err
	}
	if strings.HasSuffix(in, ".sim") {
		return []string{in}, nil
	}
	data, err := os.ReadFile(in)
	if err != nil {
		return nil, err
	}
	var paths []string
	for _, line := range strings.Split(string(data), "\n") {
		if line = strings.TrimSpace(line); line != "" {
			paths = append(paths, line)
		}
	}
	return paths, nil
}

// --- trace parsing ------------------------------------------------------------------------------

type simStep struct {
	line   int
	kind   string
	pid    int // open (the session's process), spawn, exit, kill
	sid    string
	mode   string
	sql    string
	params map[string]string
}

type simTrace struct {
	header map[string]string
	steps  []simStep
}

func simParse(text string) (simTrace, error) {
	tr := simTrace{header: map[string]string{}}
	for n, raw := range strings.Split(text, "\n") {
		line := strings.TrimRight(raw, "\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(line, "#") {
			if k, v, ok := strings.Cut(strings.TrimSpace(line[1:]), ":"); ok {
				tr.header[strings.TrimSpace(k)] = strings.TrimSpace(v)
			}
			continue
		}
		fields := strings.Fields(line)
		st := simStep{line: n + 1, kind: fields[0], params: map[string]string{}}
		params := func(kvs []string) error {
			for _, kv := range kvs {
				k, v, ok := strings.Cut(kv, "=")
				if !ok {
					return fmt.Errorf("line %d: bad parameter %q", n+1, kv)
				}
				st.params[k] = v
			}
			return nil
		}
		switch st.kind {
		case "open":
			if len(fields) != 3 && len(fields) != 4 {
				return tr, fmt.Errorf("line %d: open <sid> read|write [p<N>]", n+1)
			}
			st.sid, st.mode = fields[1], fields[2]
			if len(fields) == 4 {
				pid, err := simPid(fields[3])
				if err != nil {
					return tr, fmt.Errorf("line %d: %v", n+1, err)
				}
				st.pid = pid
			}
		case "spawn", "exit", "kill", "disconnect":
			if len(fields) != 2 {
				return tr, fmt.Errorf("line %d: %s p<N>", n+1, st.kind)
			}
			pid, err := simPid(fields[1])
			if err != nil {
				return tr, fmt.Errorf("line %d: %v", n+1, err)
			}
			st.pid = pid
		case "on":
			if len(fields) < 3 {
				return tr, fmt.Errorf("line %d: on <sid> <sql>", n+1)
			}
			st.sid = fields[1]
			rest := strings.TrimSpace(line[len("on"):])
			st.sql = strings.TrimSpace(rest[len(st.sid):])
		case "commit", "rollback", "close":
			if len(fields) != 2 {
				return tr, fmt.Errorf("line %d: %s <sid>", n+1, st.kind)
			}
			st.sid = fields[1]
		case "fault", "crash":
			if len(fields) < 2 {
				return tr, fmt.Errorf("line %d: %s <kind> [k=v ...]", n+1, st.kind)
			}
			st.mode = fields[1]
			if err := params(fields[2:]); err != nil {
				return tr, err
			}
		case "clock":
			if len(fields) != 2 || !strings.HasPrefix(fields[1], "+") {
				return tr, fmt.Errorf("line %d: clock +<micros>", n+1)
			}
			st.params["delta"] = fields[1][1:]
		case "attach":
			if len(fields) != 2 || fields[1] == "main" || fields[1] == "temp" {
				return tr, fmt.Errorf("line %d: attach <name>", n+1)
			}
			st.sid = fields[1]
		case "compact":
			if len(fields) > 2 {
				return tr, fmt.Errorf("line %d: compact [<database>]", n+1)
			}
			st.sid = "main"
			if len(fields) == 2 {
				st.sid = fields[1]
			}
		case "change_key", "rekey":
			// S12: a credential change or rekey of main to simulation key 1–3.
			if len(fields) != 2 || (fields[1] != "1" && fields[1] != "2" && fields[1] != "3") {
				return tr, fmt.Errorf("line %d: %s 1|2|3", n+1, st.kind)
			}
			st.sid = fields[1]
		case "corrupt":
			if err := params(fields[1:]); err != nil {
				return tr, err
			}
		case "backup":
			if (len(fields) != 2 && len(fields) != 3) || (fields[1] != "page_identical" && fields[1] != "compacted") {
				return tr, fmt.Errorf("line %d: backup page_identical|compacted [p<N>]", n+1)
			}
			st.mode, st.pid = fields[1], -1 // no p<N>: the lowest running process
			if len(fields) == 3 {
				pid, err := simPid(fields[2])
				if err != nil {
					return tr, fmt.Errorf("line %d: %v", n+1, err)
				}
				st.pid = pid
			}
		case "check", "reopen", "tick":
		default:
			return tr, fmt.Errorf("line %d: unknown step %q", n+1, st.kind)
		}
		tr.steps = append(tr.steps, st)
	}
	if tr.header["format"] != "simulation" {
		return tr, errors.New("missing `# format: simulation` header")
	}
	return tr, nil
}

// simPid parses a process name, p<N>.
func simPid(name string) (int, error) {
	pid, err := strconv.Atoi(strings.TrimPrefix(name, "p"))
	if !strings.HasPrefix(name, "p") || err != nil || pid < 0 {
		return 0, fmt.Errorf("bad process %q (want p<N>)", name)
	}
	return pid, nil
}

func (st simStep) intParam(key string) int {
	n, _ := strconv.Atoi(st.params[key])
	return n
}

// simFaultOf builds the fault a `fault` step arms (simulation-testing.md §6.3).
func simFaultOf(st simStep) (*simFault, error) {
	switch st.mode {
	case "power_loss":
		return &simFault{kind: simPowerLoss, survive: st.intParam("survive"), tear: st.intParam("tear"), nth: st.intParam("nth")}, nil
	case "process_crash":
		return &simFault{kind: simProcessCrash, issue: st.intParam("issue"), nth: st.intParam("nth")}, nil
	case "io_error":
		switch st.params["op"] {
		case "write":
			return &simFault{kind: simIOWrite, p: st.intParam("p")}, nil
		case "sync":
			return &simFault{kind: simIOSync, nth: st.intParam("nth")}, nil
		}
	case "read_error":
		return &simFault{kind: simReadError, p: st.intParam("p")}, nil
	case "enospc":
		return &simFault{kind: simENOSPC}, nil
	case "spill_error":
		return &simFault{kind: simSpillError, p: st.intParam("p")}, nil
	case "disconnect":
		return &simFault{kind: simDisconnect, nth: st.intParam("nth")}, nil
	}
	return nil, fmt.Errorf("line %d: unsupported fault %s %v", st.line, st.mode, st.params)
}

// --- the run ------------------------------------------------------------------------------------

type simResult struct {
	name           string
	steps          int
	violation      string
	violationStep  int
	transcriptHash uint64
	opsHash        uint64
}

func (r simResult) json() string {
	status := "pass"
	if r.violation != "" {
		status = "fail"
	}
	return fmt.Sprintf(`{"trace":%s,"core":"go","status":%q,"steps":%d,"violation":%s,"violation_step":%d,"transcript_hash":"%016x","ops_hash":"%016x"}`,
		simJSONString(r.name), status, r.steps, simJSONString(r.violation), r.violationStep, r.transcriptHash, r.opsHash)
}

// simJSONString encodes s as a JSON string (a violation message may hold any character).
func simJSONString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

// simRunFile runs one trace twice — the second run is the self-determinism check (§8.5) — and
// writes the first run's transcript (and, on a violation, the crash image) under out.
func simRunFile(path, out string) simResult {
	name := strings.TrimSuffix(filepath.Base(path), ".sim")
	res := simResult{name: name, violationStep: -1}
	data, err := os.ReadFile(path)
	if err != nil {
		res.violation = "read trace: " + err.Error()
		return res
	}
	tr, err := simParse(string(data))
	if err != nil {
		res.violation = "parse trace: " + err.Error()
		return res
	}
	first := newSimRunner(tr)
	if os.Getenv("JED_SIM_IMAGES") != "" {
		first.imagePrefix = filepath.Join(out, name+".go")
	}
	first.run()
	res.steps = len(tr.steps)
	res.transcriptHash = simFNV(first.transcript.String())
	res.opsHash = first.fs.ops
	_ = os.WriteFile(filepath.Join(out, name+".go.jsonl"), []byte(first.transcript.String()), 0o644)
	if first.violation != "" {
		res.violation = first.violation
		res.violationStep = first.violationStep
		for file, text := range first.diagnostics {
			_ = os.WriteFile(filepath.Join(out, name+".go."+file), []byte(text), 0o644)
		}
		if first.stack != "" {
			_ = os.WriteFile(filepath.Join(out, name+".go.stack.txt"), []byte(first.stack), 0o644)
		}
		if first.crashImage != nil {
			_ = os.WriteFile(filepath.Join(out, name+".go.crash.img"), first.crashImage, 0o644)
		}
		return res
	}
	second := newSimRunner(tr)
	second.run()
	switch {
	case second.violation != "":
		res.violation = "nondeterministic: the second run failed: " + second.violation
		res.violationStep = second.violationStep
	case second.transcript.String() != first.transcript.String():
		res.violation = "nondeterministic: transcripts differ between two runs" + simFirstDiff(first.transcript.String(), second.transcript.String())
	case second.fs.ops != first.fs.ops:
		res.violation = "nondeterministic: storage operation logs differ between two runs"
	}
	return res
}

func simFirstDiff(a, b string) string {
	al, bl := strings.Split(a, "\n"), strings.Split(b, "\n")
	for i := 0; i < len(al) && i < len(bl); i++ {
		if al[i] != bl[i] {
			return fmt.Sprintf(" (first difference:\n  %s\n  %s)", al[i], bl[i])
		}
	}
	return ""
}

func simFNV(s string) uint64 {
	h := fnv.New64a()
	h.Write([]byte(s))
	return h.Sum64()
}

type simSession struct {
	s     *Session
	write bool
	pins  map[string]uint64 // the version of each database a read session pinned (§8.1: what it must keep seeing)
	pid   int               // the process the session lives in
	rng   uint64            // its splitmix64 stream state while another session holds the shared source
}

// simProc is one simulated process: a Database over the shared simulated filesystem, and in a
// shared trace its own lock host (S5).
type simProc struct {
	pid  int
	db   *Database
	host *simLockHost
}

// simDB is one database's oracle state (simulation-testing.md §8.1–8.3): main, or a file attachment
// (S4), each with its own versions, history, and durability floor.
type simDB struct {
	name         string
	file         string                     // its file in the simulated filesystem
	history      map[uint64]map[string]bool // version → digests of every generation attempted at it
	version      uint64                     // the published version
	lastDigest   string                     // its digest
	floor        uint64                     // recovery may never return an older version; 0: the file may vanish
	maxAttempted uint64                     // ... nor a newer one than was ever attempted

	// Bounded growth (§8.3), tracked over one process lifetime: an upper bound on the live count the
	// engine's reclamation trigger compares against, and what the previous commit left.
	high     uint32    // the page high-water now
	free     uint32    // the free list the next commit allocates from
	trail    uint32    // where that free list's trailing run below high starts (high: none)
	lacBound uint32    // ≥ the engine's live-at-last-reclamation
	last     simGrowth // the previous commit in this lifetime
	// batchOpen is whether the current step began with a relaxed batch pending on this database's file:
	// its commit allocates from the high-water and keeps the batch's pages off the free list
	// (validated-cow.md §4), so the bounded-growth assertions do not apply to it.
	batchOpen bool
	// batchPending is whether the step began with a non-empty pending set: a commit then plans inside a
	// batch and may not lower the high-water (validated-cow.md §4). Unlike batchOpen it is false after a
	// recovery whose adopted generation awaits stabilization, which the commit's own first barrier makes
	// the floor.
	batchPending bool
	// shrinkDue is set when a relaxed commit lowered the high-water: the next flush (the batch cap, close)
	// must shorten the file (format.md *Trailing truncation*, validated-cow.md §4).
	shrinkDue bool
	// ownerLost is set when an owner died: until a process observes the database again, it may have
	// recovered any version from the floor up.
	ownerLost bool
}

// simGrowth is what a commit left behind, for the next commit's bounded-growth check.
type simGrowth struct {
	reclaimed bool   // a quiet commit that must have reclaimed: its free list holds every dead page
	high      uint32 // its page high-water
	free      uint32 // its free-list length
}

func (d *simDB) addHistory(v uint64, digest string) {
	if d.history[v] == nil {
		d.history[v] = map[string]bool{}
	}
	d.history[v][digest] = true
}

type simRunner struct {
	tr         simTrace
	seed       uint64
	pageSize   uint32
	cacheBytes int
	clock      int64

	// Handle settings from the header (simulation-testing.md §5, slice S3), applied at every open.
	workMem         int   // a session's work_mem
	tempBuffers     int   // a session's temp_buffers: past it, a temp domain spills (temp-tables.md §6)
	maxQueryMemory  int64 // a trace session's max_query_memory_bytes (the oracles' own reads are unlimited)
	maxStorageBytes int64 // the database's max_storage_bytes
	// relaxed is the header's synchronous = off (validated-cow.md §4): every process batches its
	// barriers, flushing inline so the barrier lands in the step that reached the batch cap.
	relaxed bool

	fs       *simFS
	db       *Database // the database of the process running the current step
	sessions map[string]*simSession

	// env is every process's Environment: random is its seeded source, whose stream is switched per
	// session (useSession) so each session keeps the independent stream it was opened with, and the
	// clock reads r.clock.
	env    *Environment
	random *SeededRandom
	active *simSession // the session whose stream random currently holds

	// Processes (simulation-testing.md §14 S8). A single-process trace has only p0, opened without
	// coordination; a `# processes: service` trace opens every process under the page service, over the
	// simulated lock host and network: the first is the owner, later ones its clients.
	service bool
	net     *simNet
	procs   map[int]*simProc
	cur     int // the process running the current step
	locks   *simLockTable
	armed   *simFault

	transcript strings.Builder

	// Oracle state (simulation-testing.md §8.1–8.3), one per database: main first, then each file
	// attachment (S4) in name order.
	dbs map[string]*simDB

	violation     string
	violationStep int
	crashImage    []byte
	stack         string // the goroutine stack of a panic violation

	lastDigestText string            // the text the most recent digest folded
	digestErr      error             // why the most recent digest failed
	diagnostics    map[string]string // artifact name → contents, written on a violation
	imagePrefix    string            // when set, each recovery's image is written to <prefix>.step<N>[.<db>].img
	backups        int               // backup steps run, naming each destination

	// Encryption at rest (slice S12, spec/fileformat/encrypted.md): main is encrypted under simulation
	// key key (simKeys), its key entropy seeded by the trace's seed.
	encrypted bool
	key       int
	// keyChange is a credential change or rekey of this step: [old key, new key]. Recovery after it
	// probes the key block, which exactly one of them must unlock.
	keyChange *[2]int
}

// simKeys are the simulation's host keys (S12): key n is 32 bytes of 0x4A + n, so key 0 is the
// goldens' (spec/fileformat/verify.rb tries all four on an encrypted image).
var simKeys = func() [4]*Credential {
	var out [4]*Credential
	for n := range out {
		out[n] = KeyCredential(filledKey(byte(0x4A + n)))
	}
	return out
}()

// credential is main's credential: simulation key r.key, or nil for a plaintext trace.
func (r *simRunner) credential() *Credential {
	if !r.encrypted {
		return nil
	}
	return simKeys[r.key]
}

// simUnlocks reports whether key k unwraps image's key block.
func (r *simRunner) simUnlocks(image []byte, k int) bool {
	ps := int(r.pageSize)
	_, err := unlockCodec(image[2*ps:3*ps], image[3*ps:4*ps], simKeys[k], OSRandomSource())
	return err == nil
}

// settleKey runs after a crash that interrupted a credential change or rekey (S12): exactly one of the
// old and new keys unlocks main's key block, and the new one when the step had succeeded (its last
// barrier ran). The runner continues with whichever unlocks.
func (r *simRunner) settleKey(i int, image []byte) bool {
	change := r.keyChange
	r.keyChange = nil
	if change == nil {
		return r.followKey(i, image)
	}
	old, next := change[0], change[1]
	if len(image) < 4*int(r.pageSize) {
		r.fail(i, "encryption: the key block is gone")
		return false
	}
	acknowledged := r.key == next
	if old == next {
		// A change to the key already in use: it must still unlock.
		if !r.simUnlocks(image, next) {
			r.fail(i, "encryption: key %d no longer unlocks main", next)
			return false
		}
		r.emit(`{"i":%d,"op":"unlocked","key":%d}`, i, next)
		return true
	}
	a, b := r.simUnlocks(image, old), r.simUnlocks(image, next)
	switch {
	case a && !b && !acknowledged:
		r.key = old
	case !a && b:
		r.key = next
	case a && !b:
		r.fail(i, "durability: the acknowledged change to key %d was lost", next)
		return false
	default:
		r.fail(i, "encryption: key %d unlocks: %v, key %d unlocks: %v; want exactly one", old, a, next, b)
		return false
	}
	r.emit(`{"i":%d,"op":"unlocked","key":%d}`, i, r.key)
	return true
}

// followKey is recovery outside a key step: a rekey whose rename was not yet durable in its directory
// may come back as the older file under its older key (validated-cow.md §3), so main opens with
// whichever simulation key unlocks the recovered key block, the current one first.
func (r *simRunner) followKey(i int, image []byte) bool {
	if !r.encrypted || len(image) < 4*int(r.pageSize) {
		return true
	}
	order := []int{r.key}
	for k := 0; k < 4; k++ {
		if k != r.key {
			order = append(order, k)
		}
	}
	for _, k := range order {
		if r.simUnlocks(image, k) {
			if k != r.key {
				r.key = k
				r.emit(`{"i":%d,"op":"unlocked","key":%d}`, i, k)
			}
			return true
		}
	}
	r.fail(i, "encryption: no simulation key unlocks main")
	return false
}

func newSimRunner(tr simTrace) *simRunner {
	seed, _ := strconv.ParseUint(tr.header["seed"], 10, 64)
	ps, _ := strconv.Atoi(tr.header["page_size"])
	if ps == 0 {
		ps = 256
	}
	cache, _ := strconv.Atoi(tr.header["cache_bytes"])
	clock, _ := strconv.ParseInt(tr.header["clock"], 10, 64)
	sector, _ := strconv.Atoi(tr.header["sector"])
	if sector <= 0 {
		sector = simSectorDefault
	}
	workMem, _ := strconv.Atoi(tr.header["work_mem"])
	tempBuffers, _ := strconv.Atoi(tr.header["temp_buffers"])
	maxQueryMemory, _ := strconv.ParseInt(tr.header["max_query_memory_bytes"], 10, 64)
	maxStorageBytes, _ := strconv.ParseInt(tr.header["max_storage_bytes"], 10, 64)
	r := &simRunner{
		tr:              tr,
		seed:            seed,
		pageSize:        uint32(ps),
		cacheBytes:      cache,
		clock:           clock,
		workMem:         workMem,
		tempBuffers:     tempBuffers,
		maxQueryMemory:  maxQueryMemory,
		maxStorageBytes: maxStorageBytes,
		relaxed:         tr.header["synchronous"] == "off",
		fs:              newSimFS(seed, sector, uint32(ps)),
		sessions:        map[string]*simSession{},
		service:         tr.header["processes"] == "service",
		net:             newSimNet(),
		procs:           map[int]*simProc{},
		dbs:             map[string]*simDB{},
		violationStep:   -1,
	}
	r.random = NewSeededRandom(0)
	b := NewEnvironmentBuilder()
	b.SetRandomSource(r.random)
	b.SetClockSource(simClock{now: &r.clock})
	if tr.header["encrypted"] == "1" {
		// Seeded so the cores' images stay byte-identical (encrypted.md §8).
		b.SetInsecureSeededKeyEntropy(seed)
		r.encrypted = true
	}
	r.env = b.Build()
	return r
}

// simClock is the simulation's clock source: it reads the runner's clock, which only clock steps
// move. Not goroutine-safe — a simulation runs on one goroutine.
type simClock struct{ now *int64 }

func (c simClock) NowMicros() int64 { return *c.now }

// useSession makes the shared seeded source continue ss's stream, saving the previously active
// session's position, so every session draws its own stream (the one seeded at its open) however
// sessions interleave.
func (r *simRunner) useSession(ss *simSession) {
	if r.active == ss {
		return
	}
	if r.active != nil {
		r.active.rng = r.random.state
	}
	r.random.Reseed(ss.rng)
	r.active = ss
}

func (r *simRunner) fail(step int, format string, args ...any) {
	if r.violation == "" {
		where := "setup: "
		if step >= 0 {
			where = fmt.Sprintf("step %d (line %d): ", step, r.tr.steps[step].line)
		}
		r.violation = where + fmt.Sprintf(format, args...)
		r.violationStep = step
	}
}

func (r *simRunner) emit(format string, args ...any) {
	fmt.Fprintf(&r.transcript, format, args...)
	r.transcript.WriteByte('\n')
}

// main is the main database's oracle state.
func (r *simRunner) main() *simDB { return r.dbs["main"] }

// attachedNames lists the attachments the runner tracks, in name order.
func (r *simRunner) attachedNames() []string {
	var names []string
	for name := range r.dbs {
		if name != "main" {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	return names
}

// order lists every tracked database: main, then the attachments in name order.
func (r *simRunner) order() []*simDB {
	out := []*simDB{r.main()}
	for _, name := range r.attachedNames() {
		out = append(out, r.dbs[name])
	}
	return out
}

func newSimDB(name, file string) *simDB {
	return &simDB{name: name, file: file, history: map[uint64]map[string]bool{}}
}

// open opens a Database over the simulated disk through the ordinary demand-paged loader — the
// path a reopening process takes, including validated-COW recovery (validated-cow.md §1) — and
// re-attaches every tracked attachment whose file exists.
func (r *simRunner) open() error {
	if err := r.openProc(0); err != nil {
		return err
	}
	if r.service {
		return nil // openProc re-attached them
	}
	for _, name := range r.attachedNames() {
		d := r.dbs[name]
		if r.fs.files[d.file] == nil {
			continue // the caller decides whether losing it was allowed
		}
		if err := r.attach(name); err != nil {
			return fmt.Errorf("re-attach %s: %w", name, err)
		}
	}
	return nil
}

// attach attaches the existing file of attachment name read-write to the current process: under the
// page service in a service trace (owner or page client of the file, README.md §6.6), uncoordinated
// otherwise.
func (r *simRunner) attach(name string) error {
	locking := LockingNone
	if r.service {
		locking = LockingAuto
	}
	return r.db.Attach(name, AttachFileWithOptions(r.dbs[name].file, AttachFileOptions{Locking: locking}), false)
}

// openProc starts process pid. A service trace elects it through the simulated lock host and
// network, exactly as OpenDatabaseWithOptions does through the OS host.
func (r *simRunner) openProc(pid int) error {
	var db *Database
	var err error
	if r.service {
		db, err = r.openServiceProc(pid)
	} else {
		db, err = r.openDatabase(nil)
	}
	if err != nil {
		return err
	}
	r.procs[pid] = &simProc{pid: pid, db: db}
	r.cur, r.db = pid, db
	if r.service {
		// Every process attaches every tracked attachment whose file exists: the owner of the file, or
		// a page client of whichever process owns it.
		for _, name := range r.attachedNames() {
			if r.fs.files[r.dbs[name].file] == nil {
				continue
			}
			if err := r.attach(name); err != nil {
				_ = r.closeProc(pid)
				return fmt.Errorf("re-attach %s: %w", name, err)
			}
		}
		r.net.settle()
	}
	return nil
}

// simServiceGraceMs is a simulated owner's shutdown grace: its clients' pinned readers live in other
// processes, which no single step can end, so a closing owner always waits out the grace.
const simServiceGraceMs = 1000

// openServiceProc opens process pid under the page service (S8): its own lock host over the shared
// lock table and network, the simulated filesystem and spill host, and no background re-election, so a
// client re-elects at its next transaction begin, in trace order. Every owner limit that would start a
// timer is off.
func (r *simRunner) openServiceProc(pid int) (*Database, error) {
	if r.locks == nil {
		r.locks = newSimLockTable(&r.clock, r.procBusy)
	}
	host := &simLockHost{table: r.locks, pidNum: pid, claimed: map[string]bool{}, net: r.net}
	zero, grace, timeout := uint64(0), uint64(simServiceGraceMs), uint64(defaultFileLockTimeoutMs)
	opts := OpenOptions{
		CacheBytes:                 r.cacheBytes,
		FileLockTimeoutMs:          &timeout,
		IdleInTransactionTimeoutMs: &zero,
		IdleSessionTimeoutMs:       &zero,
		ShutdownGraceMs:            &grace,
		Environment:                r.env,
		MaxStorageBytes:            r.maxStorageBytes,
	}
	if r.relaxed {
		opts.Synchronous = SynchronousOff
	}
	h := newServiceHandoff(host, simDiskPath, opts)
	h.files, h.spill, h.background = r.fs, r.fs.spillHost(), false
	db, err := openServiceWith(h, true)
	if err != nil {
		r.locks.release(pid)
		r.net.kill(pid)
		r.net.settle()
		return nil, err
	}
	db.core.storage.inlineFlush = true // every flush lands in the step that caused it
	r.net.settle()
	return db, nil
}

// ownerPid is the running process that owns the main database under the page service, or -1.
func (r *simRunner) ownerPid() int { return r.ownerPidOf(r.main()) }

// ownerPidOf is the running process that owns database d under the page service, or -1.
func (r *simRunner) ownerPidOf(d *simDB) int {
	for _, pid := range r.livePids() {
		if c := simServiceCore(r.procs[pid].db, d); c != nil && c.pageOwner() != nil {
			return pid
		}
	}
	return -1
}

// simServiceCore is the core whose page-service role serves database d in db: the handle's own for
// main, an attachment's inner handle's (README.md §6.6), or nil when d is not attached under the
// service.
func simServiceCore(db *Database, d *simDB) *sharedCore {
	if d.name == "main" {
		return db.core
	}
	if att := db.core.attachment(d.name); att != nil && att.svc != nil {
		return att.svc.core
	}
	return nil
}

// procBusy reports whether pid's presence probe would block: it takes the process's own writer gate,
// which an open write session holds (a real probe would wait for that writer to finish).
func (r *simRunner) procBusy(pid int) bool {
	for _, ss := range r.sessions {
		if ss.pid == pid && ss.write {
			return true
		}
	}
	return false
}

func (r *simRunner) openDatabase(coord *fileCoordinator) (*Database, error) {
	main := r.fs.main()
	if main == nil {
		return nil, newError(IoError, "the database file is gone")
	}
	p, err := pagerFromStore(main)
	if err != nil {
		return nil, err
	}
	cache := r.cacheBytes
	if cache <= 0 {
		cache = defaultCacheBytes
	}
	e, err := loadEnginePagedCredential(p, cacheLeaves(cache, p.pageSize), r.env, r.credential())
	if err != nil {
		return nil, err
	}
	e.path = simDiskPath
	// A writable open finishes a credential change a crash interrupted (encrypted.md §5).
	if err := e.repairKeyBlock(); err != nil {
		return nil, err
	}
	// Spill and temp-table spill scratch files, whose operations can fail; sealed for an encrypted
	// database (encryption.md §6).
	e.spill = sealScratch(r.fs.spillHost(), r.encrypted, r.env)
	db := databaseOver(sharedCoreFromEngineCoordinated(e, coord))
	db.core.storage.files = r.fs // create, compaction, and attachments go through the simulated filesystem
	db.core.storage.relaxed = r.relaxed
	db.core.storage.inlineFlush = true // every flush lands in the step that caused it
	if r.maxStorageBytes > 0 {
		if err := db.SetMaxStorageBytes("main", r.maxStorageBytes); err != nil {
			return nil, err
		}
	}
	return db, nil
}

func (r *simRunner) run() {
	if p := r.tr.header["processes"]; p != "" && p != "service" {
		r.violation = "unsupported processes mode " + p
		return
	}
	// Create the database through the simulated filesystem, as the host's create does: a temp file,
	// its sync, the rename, and the directory barrier (S4).
	e, err := createVia(r.fs, simDiskPath, databaseOptions{PageSize: r.pageSize, env: r.env, credential: r.credential()})
	if err != nil {
		r.violation = "create: " + err.Error()
		return
	}
	_ = e.Close()
	m := newSimDB("main", simDiskPath)
	r.dbs["main"] = m
	if err := r.open(); err != nil {
		r.violation = "initial open: " + err.Error()
		return
	}
	m.version = r.db.Version()
	m.floor, m.maxAttempted = m.version, m.version
	d, ok := r.committedDigest(m)
	if !ok {
		r.violation = "initial digest failed"
		return
	}
	m.lastDigest = d
	m.addHistory(m.version, d)
	r.observeGrowth(m)
	for i := range r.tr.steps {
		if !r.step(i) || r.violation != "" {
			return
		}
	}
}

// image copies a database file's cache — what a new process would open — or nil if it is gone.
func (r *simRunner) image(d *simDB) []byte {
	if f := r.fs.files[d.file]; f != nil {
		return append([]byte(nil), f.cache...)
	}
	return nil
}

func (r *simRunner) mainImage() []byte { return r.image(r.main()) }

// step runs one trace step; false stops the run. A panic anywhere is a violation.
func (r *simRunner) step(i int) (cont bool) {
	defer func() {
		if p := recover(); p != nil {
			r.fail(i, "panic: %v", p)
			r.stack = string(debug.Stack())
			cont = false
		}
	}()
	st := r.tr.steps[i]
	switch st.kind {
	case "fault":
		f, err := simFaultOf(st)
		if err != nil {
			r.fail(i, "%v", err)
			return false
		}
		r.armed = f
		r.emit(`{"i":%d,"op":"fault","kind":%q}`, i, st.mode)
		return true
	case "crash":
		r.fs.beginStep(uint64(i), nil)
		if st.mode == "power" {
			r.fs.powerLoss(uint64(i), st.intParam("survive"), st.intParam("tear"))
		}
		return r.recover(i, "none")
	case "clock":
		delta, _ := strconv.ParseInt(st.params["delta"], 10, 64)
		r.clock += delta
		r.emit(`{"i":%d,"op":"clock"}`, i)
		return true
	case "tick":
		r.emit(`{"i":%d,"op":"tick"}`, i)
		return true
	case "disconnect":
		// The process's connection to the owner ends (S8): both ends see end of stream.
		p := r.procs[st.pid]
		var cl *psClient
		if p != nil {
			cl = p.db.core.pageClient()
		}
		if cl == nil {
			r.emit(`{"i":%d,"op":"disconnect","pid":%d,"skip":true}`, i, st.pid)
			return true
		}
		cl.conn.(*simConnEnd).drop()
		r.net.settle()
		r.emit(`{"i":%d,"op":"disconnect","pid":%d}`, i, st.pid)
		return true
	case "exit":
		if r.procs[st.pid] == nil {
			r.emit(`{"i":%d,"op":"exit","pid":%d,"skip":true}`, i, st.pid)
			return true
		}
		if err := r.closeProc(st.pid); err != nil {
			r.fail(i, "exit p%d: %v", st.pid, err)
			return false
		}
		r.emit(`{"i":%d,"op":"exit","pid":%d}`, i, st.pid)
		return true
	case "kill":
		if r.procs[st.pid] == nil {
			r.emit(`{"i":%d,"op":"kill","pid":%d,"skip":true}`, i, st.pid)
			return true
		}
		r.dropProc(st.pid)
		if len(r.procs) == 0 {
			r.fs.beginStep(uint64(i), nil)
			return r.recover(i, "none")
		}
		r.emit(`{"i":%d,"op":"kill","pid":%d}`, i, st.pid)
		return true
	case "corrupt":
		r.fs.beginStep(uint64(i), nil)
		return r.stepCorrupt(i, st)
	}

	// A step that needs a process when none is running (the last one exited) restarts p0 first.
	if len(r.procs) == 0 && st.kind != "spawn" {
		r.fs.beginStep(uint64(i), nil)
		r.stepSpawn(i, 0)
		if r.violation != "" || len(r.procs) == 0 {
			if r.violation == "" {
				r.fail(i, "p0 could not restart")
			}
			return false
		}
	}
	armed := r.armed
	r.armed = nil
	start := map[string]uint64{}
	for name, d := range r.dbs {
		start[name] = d.version
		d.batchOpen = r.relaxed && !r.engineFlushed(d)
		d.batchPending = r.relaxed && r.enginePending(d)
	}
	if pid, ok := r.stepPid(st); ok {
		if st.kind != "spawn" && !r.selectProc(pid) {
			if st.kind == "open" {
				r.emit(`{"i":%d,"op":"open","sid":%q,"skip":true}`, i, st.sid)
				return true
			}
			if st.kind == "backup" {
				r.emit(`{"i":%d,"op":"backup","pid":%d,"skip":true}`, i, st.pid)
				return true
			}
			if len(r.procs) == 0 {
				r.fail(i, "no process is running")
				return false
			}
		}
	}
	diskFault := armed
	if armed != nil && armed.kind == simDisconnect {
		diskFault = nil
		r.net.beginStep(armed.nth)
	} else {
		r.net.beginStep(0)
	}
	r.fs.beginStep(uint64(i), diskFault)
	switch st.kind {
	case "spawn":
		r.stepSpawn(i, st.pid)
	case "open":
		r.stepOpen(i, st)
	case "on":
		r.stepOn(i, st)
	case "commit":
		r.stepCommit(i, st)
	case "rollback", "close":
		r.stepEnd(i, st)
	case "check":
		r.stepCheck(i)
	case "compact":
		r.stepCompact(i, st.sid, 0)
	case "rekey":
		n, _ := strconv.Atoi(st.sid)
		r.stepCompact(i, "main", n)
	case "change_key":
		n, _ := strconv.Atoi(st.sid)
		r.stepChangeKey(i, n)
	case "backup":
		r.stepBackup(i, st)
	case "attach":
		r.stepAttach(i, st.sid)
	case "reopen":
		if !r.stepReopen(i) {
			return false
		}
	}
	if r.service {
		r.net.settle()
	}
	if r.violation != "" {
		return false
	}
	// A completed barrier made every earlier write durable: the generation a database published when
	// the step began can no longer be lost (§8.2).
	for name, d := range r.dbs {
		f := r.fs.files[d.file]
		if f == nil {
			continue
		}
		// Under synchronous = off a barrier proves the step's starting version durable only when the
		// engine was not batching then: a pending version may be durable by accident (a file growth is
		// a full fsync) and still be overwritten by the next commit of its batch (validated-cow.md §4).
		if f.barrierOK && !d.batchOpen && start[name] > d.floor {
			d.floor = start[name]
		}
		if !r.relaxed || r.fs.dead || r.fs.fired != "" || d.version <= d.floor || !r.engineFlushed(d) || !r.fs.entryDurable(d.file) {
			continue
		}
		// The engine holds nothing pending: it treats the published version as flushed, and will
		// overwrite only the other slot. Hold it to that, after checking the claim against the disk.
		// Its directory entry must be durable too: a process that died between compaction's rename and
		// its directory barrier leaves the new file readable, and a power loss before the next opener's
		// first commit syncs the directory brings the older file back (validated-cow.md §3).
		if f.metaPending() {
			r.fail(i, "durability: the engine treats version %d of %s as flushed, but no barrier covered its meta", d.version, d.name)
			return false
		}
		d.floor = d.version
	}
	// Checked against the floor this step leaves (a flush in the step moved it).
	for _, d := range r.order() {
		if !r.checkTruncated(i, d) {
			return false
		}
	}
	if armed == nil {
		r.keyChange = nil
		return true
	}
	if armed.kind == simDisconnect {
		// A lost connection ends no process: its client re-elects at its next begin.
		fired := "end"
		if r.net.disconnected {
			fired = "frame"
		}
		r.emit(`{"i":%d,"op":"disconnected","fired":%q}`, i, fired)
		return true
	}
	// Every faulted step ends the process; a power loss also discards the unsynced writes (§5).
	fired := r.fs.fired
	if fired == "" {
		fired = "end"
	}
	if armed.kind == simPowerLoss {
		r.fs.powerLoss(uint64(i), armed.survive, armed.tear)
		return r.recover(i, fired)
	}
	// In a service trace any other fault kills the owner, the only process that touches the file,
	// whichever process's step drove its I/O; the others keep running over the same kernel state.
	if r.service && len(r.procs) > 1 {
		// Every owner — of main or of an attachment — is a process that may have touched a file after
		// the fault fired, so each dies; with attachments owned elsewhere that may be more than one.
		pids := r.ownerPids()
		if len(pids) == 0 {
			pids = []int{r.cur}
		}
		if len(pids) < len(r.procs) {
			for _, pid := range pids {
				r.dropProc(pid)
			}
			r.fs.processDeath()
			for _, pid := range pids {
				r.emit(`{"i":%d,"op":"killed","pid":%d,"fired":%q}`, i, pid, fired)
			}
			return true
		}
	}
	return r.recover(i, fired)
}

// ownerPids lists the running processes that own main or an attachment under the page service.
func (r *simRunner) ownerPids() []int {
	var pids []int
	for _, pid := range r.livePids() {
		for _, d := range r.order() {
			if c := simServiceCore(r.procs[pid].db, d); c != nil && c.pageOwner() != nil {
				pids = append(pids, pid)
				break
			}
		}
	}
	return pids
}

// dbVersion is the version of database d the current process has published.
func (r *simRunner) dbVersion(d *simDB) uint64 {
	if d.name == "main" {
		return r.db.Version()
	}
	return simAttachedVersion(r.db, d)
}

// simSessionVersion is the version of attachment name a session reads (its pinned or base root), or 0.
func simSessionVersion(s *Session, name string) uint64 {
	if snap := s.engine.attachedCommitted[name]; snap != nil {
		return snap.txid
	}
	return 0
}

// simAttachedVersion is the version of attachment d that db has adopted: an attachment under the page
// service reports its inner handle's.
func simAttachedVersion(db *Database, d *simDB) uint64 {
	if db.core.attachment(d.name) == nil {
		return 0
	}
	if snap := db.core.attachedRoot(d.name); snap != nil {
		return snap.txid
	}
	return 0
}

// versionsJSON renders the attachments' versions as `,"dbs":{"a1":V,...}`, or "" with none, so a
// trace without attachments keeps its transcript shape.
func (r *simRunner) versionsJSON(versions map[string]uint64) string {
	names := r.attachedNames()
	if len(names) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString(`,"dbs":{`)
	n := 0
	for _, name := range names {
		v, ok := versions[name]
		if !ok {
			continue
		}
		if n > 0 {
			b.WriteByte(',')
		}
		n++
		fmt.Fprintf(&b, "%q:%d", name, v)
	}
	b.WriteByte('}')
	return b.String()
}

func (r *simRunner) stepOpen(i int, st simStep) {
	if _, dup := r.sessions[st.sid]; dup {
		r.fail(i, "session %s already open", st.sid)
		return
	}
	var s *Session
	switch st.mode {
	case "read":
		s = r.db.ReadSession()
	case "write":
		for sid, ss := range r.sessions {
			if ss.write {
				r.fail(i, "open %s write while %s holds the writer gate", st.sid, sid)
				return
			}
		}
		s = r.db.WriteSession()
	default:
		r.fail(i, "unknown session mode %q", st.mode)
		return
	}
	if r.workMem > 0 {
		s.SetWorkMem(r.workMem)
	}
	if r.tempBuffers > 0 {
		s.SetTempBuffers(r.tempBuffers)
	}
	if r.maxQueryMemory > 0 {
		s.SetMaxQueryMemoryBytes(r.maxQueryMemory)
	}
	if r.service {
		d, ok := r.digest(s, r.main())
		if !r.observe(i, "session "+st.sid, s.Version(), d, ok) {
			return
		}
		for _, name := range r.attachedNames() {
			a := r.dbs[name]
			v := simSessionVersion(s, name)
			if v == 0 {
				continue
			}
			dg, ok := r.digest(s, a)
			if !r.observeDB(i, a, "session "+st.sid, v, dg, ok) {
				return
			}
		}
	}
	// A session pins every database's committed root when it opens.
	pins := map[string]uint64{"main": s.Version()}
	for _, name := range r.attachedNames() {
		if v := simSessionVersion(s, name); v != 0 {
			pins[name] = v
		}
	}
	r.sessions[st.sid] = &simSession{s: s, write: st.mode == "write", pins: pins, pid: r.cur, rng: simDecide(r.seed, simLaneSession, uint64(i), 0, 0)}
	r.emit(`{"i":%d,"op":"open","sid":%q,"version":%d%s}`, i, st.sid, s.Version(), r.versionsJSON(pins))
}

func simCode(err error) string {
	var ee *EngineError
	if errors.As(err, &ee) {
		return ee.Code()
	}
	return "non-engine error: " + err.Error()
}

func (r *simRunner) stepOn(i int, st simStep) {
	ss, ok := r.sessions[st.sid]
	if !ok {
		r.emit(`{"i":%d,"op":"on","sid":%q,"skip":true}`, i, st.sid)
		return
	}
	r.useSession(ss)
	n, affected, hash, cost, err := simQuery(ss.s, st.sql)
	if err != nil {
		code := simCode(err)
		if strings.HasPrefix(code, "non-engine") {
			r.fail(i, "%s", code)
			return
		}
		r.emit(`{"i":%d,"op":"on","sid":%q,"error":%q}`, i, st.sid, code)
		if code == "XX001" {
			r.fail(i, "corruption: a statement reported XX001: %v", err)
		}
		return
	}
	r.emit(`{"i":%d,"op":"on","sid":%q,"rows":%d,"affected":%d,"hash":"%016x","cost":%d}`, i, st.sid, n, affected, hash, cost)
}

// simQuery runs sql and folds its rendered rows, sorted (row order is not what this harness
// tests), into an FNV-1a hash.
func simQuery(s *Session, sql string) (n int, affected int64, hash uint64, cost int64, err error) {
	rows, err := s.Query(context.Background(), sql)
	if err != nil {
		return 0, 0, 0, 0, err
	}
	defer rows.Close()
	var rendered []string
	for rows.Next() {
		cells := make([]string, 0, len(rows.Row()))
		for _, v := range rows.Row() {
			text, err := s.Render(v)
			if err != nil {
				return 0, 0, 0, 0, err
			}
			cells = append(cells, text)
		}
		rendered = append(rendered, strings.Join(cells, "\x1f"))
	}
	if err := rows.Err(); err != nil {
		return 0, 0, 0, 0, err
	}
	sort.Strings(rendered)
	affected = -1
	if a, ok := rows.RowsAffected(); ok {
		affected = a
	}
	return len(rendered), affected, simFNV(strings.Join(rendered, "\x1e")), rows.Cost(), nil
}

// simDigestRelations is the catalog part of the logical digest (§8.1).
var simDigestRelations = []string{"jed_tables", "jed_columns", "jed_indexes", "jed_constraints", "jed_sequences"}

// simQualifier is the prefix that names database d's relations: none for main, `name.` for an
// attachment.
func simQualifier(d *simDB) string {
	if d.name == "main" {
		return ""
	}
	return d.name + "."
}

// simEmptyDigest is the digest of a freshly created database (an attachment's version 1): every
// catalog relation empty and no table.
func simEmptyDigest(d *simDB) string {
	var b strings.Builder
	for _, rel := range simDigestRelations {
		b.WriteString("SELECT * FROM " + simQualifier(d) + rel + "\n\n\n")
	}
	return fmt.Sprintf("%016x", simFNV(b.String()))
}

// digest is the logical digest of what s sees of database d: the catalog relations plus every
// table's rows, all rendered and sorted, folded with FNV-1a. ok is false if any query failed (an
// aborted block, say); r.digestErr then holds that error.
func (r *simRunner) digest(s *Session, d *simDB) (string, bool) {
	r.digestErr = nil
	// An armed read fault targets the trace's statements, not the oracle checking them.
	r.fs.oracle = true
	defer func() { r.fs.oracle = false }()
	// The oracle's own reads must not trip a trace session's memory limit.
	if limit := s.MaxQueryMemoryBytes(); limit > 0 {
		s.SetMaxQueryMemoryBytes(0)
		defer s.SetMaxQueryMemoryBytes(limit)
	}
	q := simQualifier(d)
	var b strings.Builder
	var tables []string
	r.lastDigestText = ""
	fold := func(sql string) bool {
		rows, err := s.Query(context.Background(), sql)
		if err != nil {
			r.digestErr = err
			r.lastDigestText = b.String() + sql + "\nERROR: " + err.Error() + "\n"
			return false
		}
		defer rows.Close()
		var rendered []string
		for rows.Next() {
			cells := make([]string, 0, len(rows.Row()))
			for _, v := range rows.Row() {
				text, err := s.Render(v)
				if err != nil {
					r.digestErr = err
					return false
				}
				cells = append(cells, text)
			}
			if strings.HasSuffix(sql, "jed_tables") {
				tables = append(tables, cells[0])
			}
			rendered = append(rendered, strings.Join(cells, "\x1f"))
		}
		if err := rows.Err(); err != nil {
			r.digestErr = err
			r.lastDigestText = b.String() + sql + "\nERROR: " + err.Error() + "\n"
			return false
		}
		sort.Strings(rendered)
		b.WriteString(sql)
		b.WriteByte('\n')
		b.WriteString(strings.Join(rendered, "\n"))
		b.WriteString("\n\n")
		return true
	}
	for _, rel := range simDigestRelations {
		if !fold("SELECT * FROM " + q + rel) {
			return "", false
		}
	}
	sort.Strings(tables)
	for _, t := range tables {
		if !fold(`SELECT * FROM ` + q + `"` + t + `"`) {
			return "", false
		}
	}
	r.lastDigestText = b.String()
	return fmt.Sprintf("%016x", simFNV(b.String())), true
}

// checkLive runs the live integrity checker with read faults suspended, like every oracle read.
func (r *simRunner) checkLive() error {
	if r.db.core.pageClient() != nil {
		// A page client reads pages only under a pinned transaction; its trees are the owner's pages,
		// which the owner's own live check covers.
		return nil
	}
	r.fs.oracle = true
	defer func() { r.fs.oracle = false }()
	return simCheckLive(r.db)
}

// committedView is the version and digest of database d a fresh read session sees.
func (r *simRunner) committedView(d *simDB) (uint64, string, bool) {
	rs := r.db.ReadSession()
	defer rs.Close()
	digest, ok := r.digest(rs, d)
	return r.dbVersion(d), digest, ok
}

func (r *simRunner) committedDigest(d *simDB) (string, bool) {
	rs := r.db.ReadSession()
	defer rs.Close()
	return r.digest(rs, d)
}

// quiet reports whether the commit being checked ran with nothing that may hold reclamation back: no
// other session (a reader pins its snapshot), no other process (co-resident commits are append-only),
// and no fault.
func (r *simRunner) quiet() bool {
	return !r.service && len(r.sessions) == 0 && r.fs.fault == nil
}

func (r *simRunner) stepCommit(i int, st simStep) {
	ss, ok := r.sessions[st.sid]
	if !ok {
		r.emit(`{"i":%d,"op":"commit","sid":%q,"skip":true}`, i, st.sid)
		return
	}
	delete(r.sessions, st.sid)
	dbs := r.order()
	type inflight struct {
		digest, text string
		ok           bool
	}
	before := make([]inflight, len(dbs))
	for k, d := range dbs {
		if _, pinned := ss.pins[d.name]; !pinned {
			continue // attached after this session opened: it cannot have written it
		}
		dg, okd := r.digest(ss.s, d)
		before[k] = inflight{dg, r.lastDigestText, okd}
	}
	err := ss.s.Commit()
	if err != nil {
		code := simCode(err)
		if strings.HasPrefix(code, "non-engine") {
			r.fail(i, "%s", code)
			return
		}
		r.emit(`{"i":%d,"op":"commit","sid":%q,"error":%q}`, i, st.sid, code)
		if code == "XX001" {
			r.fail(i, "corruption: commit reported XX001: %v", err)
			return
		}
		for k, d := range dbs {
			if _, pinned := ss.pins[d.name]; !pinned {
				continue
			}
			if now := r.dbVersion(d); now != d.version {
				r.fail(i, "a failed commit published version %d of %s (was %d)", now, d.name, d.version)
				return
			}
			// The commit reached storage, so a crash may still recover its generation (§8.1).
			if f := r.fs.files[d.file]; f != nil && f.writes > 0 && before[k].ok {
				d.addHistory(d.version+1, before[k].digest)
				d.maxAttempted = max(d.maxAttempted, d.version+1)
			}
		}
		return
	}
	versions := map[string]uint64{}
	for _, d := range dbs {
		versions[d.name] = r.dbVersion(d)
	}
	role := ""
	if r.service {
		role = `,"role":"owner"`
		if r.db.core.pageClient() != nil {
			role = `,"role":"client"`
		}
	}
	r.emit(`{"i":%d,"op":"commit","sid":%q,"version":%d%s%s}`, i, st.sid, versions["main"], r.versionsJSON(versions), role)
	quiet := r.quiet()
	for k, d := range dbs {
		if _, pinned := ss.pins[d.name]; !pinned {
			continue // not attached in this session's process when it opened: it cannot have written it
		}
		base, now, in := d.version, versions[d.name], before[k]
		switch now {
		case base:
			if in.ok && in.digest != d.lastDigest {
				r.fail(i, "commit succeeded without publishing the transaction's changes to %s", d.name)
				return
			}
		case base + 1:
			if !in.ok {
				r.fail(i, "commit published version %d of %s from a transaction whose reads failed", now, d.name)
				return
			}
			published, ok := r.committedDigest(d)
			if !ok && r.relaxed && r.fs.fired != "" {
				// The batch cap's flush failed in this step and revoked the storage, so nothing can be read
				// back; the acknowledged commit is checked by the recovery that follows.
				published, ok = in.digest, true
			}
			if !ok && r.service && !r.fs.dead && simCode(r.digestErr) == "08006" {
				// An armed disconnect landed in this read-back's own frames: the read fails 08006, as
				// any read open across a lost connection does; a fresh read re-elects and reads again.
				published, ok = r.committedDigest(d)
			}
			if !ok && r.service && r.fs.dead {
				// The owner died later in this step (its maintenance commit hit the fault), so nothing can be
				// read back through it; the acknowledged commit is checked by the recovery that follows.
				published, ok = in.digest, true
			}
			if !ok || published != in.digest {
				r.diagnostics = map[string]string{"before-commit.txt": in.text, "after-commit.txt": r.lastDigestText}
				r.fail(i, "version %d of %s does not contain what its transaction saw before commit", now, d.name)
				return
			}
			d.addHistory(now, in.digest)
			d.version, d.lastDigest = now, in.digest
			d.maxAttempted = max(d.maxAttempted, now)
			if c := simServiceCore(r.db, d); !r.relaxed || (c != nil && c.pageClient() != nil) {
				d.floor = now // acknowledged under synchronous = on, or a page client's commit (§8.2)
			}
			r.checkGrowth(i, d, quiet)
			if r.violation != "" {
				return
			}
			if r.service {
				r.serviceCommitted(i, d, base, now, in.digest)
				if r.violation != "" {
					return
				}
			}
		default:
			r.fail(i, "commit jumped %s from version %d to %d", d.name, base, now)
			return
		}
	}
	if r.relaxed && r.fs.fired != "" {
		return // a failed cap flush revoked the storage; the recovery that follows checks it
	}
	if err := r.checkLive(); err != nil {
		r.fail(i, "after commit: %v", err)
	}
}

// serviceCommitted runs the page-service checks after a commit of main published version now over
// base (S8). A page client's commit must obey the commit-role rule (page-service.md §6): it never
// rebuilds the free list, so the free list it persists is a subset of its base's. And an owner may
// follow a client's commit with a maintenance commit — the unchanged snapshot at the next versions —
// which joins the history with the same contents.
func (r *simRunner) serviceCommitted(i int, d *simDB, base, now uint64, digest string) {
	if c := simServiceCore(r.db, d); c == nil || c.pageClient() == nil {
		return
	}
	image := r.image(d)
	before, okb := simFreeList(image, r.pageSize, base)
	after, oka := simFreeList(image, r.pageSize, now)
	if okb && oka {
		was := make(map[uint32]bool, len(before))
		for _, pg := range before {
			was[pg] = true
		}
		for _, pg := range after {
			if !was[pg] {
				r.fail(i, "commit-role rule: a page client's commit (version %d) freed page %d, which its base's free list does not hold", now, pg)
				return
			}
		}
	}
	if r.fs.dead {
		// The owner died later in this step; it may have been writing a maintenance commit, which
		// recovery may select: the same contents at the next version.
		d.addHistory(now+1, digest)
		d.maxAttempted = max(d.maxAttempted, now+1)
		return
	}
	owner := r.ownerPidOf(d)
	if owner < 0 {
		return
	}
	ov := r.procs[owner].db.Version()
	if d.name != "main" {
		ov = simAttachedVersion(r.procs[owner].db, d)
	}
	if ov <= now {
		return
	}
	for v := now + 1; v <= ov; v++ {
		d.addHistory(v, digest)
	}
	d.version, d.maxAttempted = ov, max(d.maxAttempted, ov)
	if !r.relaxed {
		d.floor = ov // the maintenance commit is an owner commit: batched under synchronous = off
	}
	if d.name == "main" {
		r.emit(`{"i":%d,"op":"maintenance","version":%d}`, i, ov)
	} else {
		r.emit(`{"i":%d,"op":"maintenance","db":%q,"version":%d}`, i, d.name, ov)
	}
}

// simFreeList reads the free list the meta slot holding version v persists, from a file image.
func simFreeList(image []byte, ps uint32, v uint64) ([]uint32, bool) {
	for slot := 0; slot < 2; slot++ {
		m, valid := readMeta(image, int(ps), slot)
		if !valid || m.txid != v {
			continue
		}
		p, err := pagerFromStore(newMemoryBlockStore(append([]byte(nil), image...)))
		if err != nil {
			return nil, false
		}
		free, err := readFreeList(newSharedPaging(p, 1), pageRef{page: m.freeListHead, tag: m.freeListTag}, m.pageCount)
		return free, err == nil
	}
	return nil, false
}

// engineFlushed reports whether the process writing database d holds no relaxed commit pending a
// flush — no pending set, no adopted generation awaiting stabilization, no failed barrier — so its
// published version is the one it treats as durable (validated-cow.md §4). Under the page service
// the owner writes the file; with no owner running, nothing is claimed.
func (r *simRunner) engineFlushed(d *simDB) bool {
	db := r.db
	if r.service {
		owner := r.ownerPidOf(d)
		if owner < 0 {
			return false
		}
		db = r.procs[owner].db
	}
	if db == nil {
		return false
	}
	st, err := db.core.withStorage(d.name)
	if err != nil || st.paging == nil {
		return false
	}
	st.mu.Lock()
	defer st.mu.Unlock()
	flushed := false
	_ = st.paging.withPager(func(p *pager) error {
		flushed = len(p.pending) == 0 && !p.recoverySync && !p.poisoned
		return nil
	})
	return flushed && st.flushing == nil
}

// enginePending reports whether the process writing database d holds a non-empty pending set — a
// relaxed batch not yet flushed (validated-cow.md §4). Not run under the page service.
func (r *simRunner) enginePending(d *simDB) bool {
	if r.service || r.db == nil {
		return false
	}
	st, err := r.db.core.withStorage(d.name)
	if err != nil || st.paging == nil {
		return false
	}
	st.mu.Lock()
	defer st.mu.Unlock()
	pending := false
	_ = st.paging.withPager(func(p *pager) error {
		pending = len(p.pending) > 0
		return nil
	})
	return pending
}

// --- bounded growth (simulation-testing.md §8.3) ------------------------------------------------

// simMetaOf reads the page high-water and live page count of the meta slot holding version v.
func simMetaOf(image []byte, ps uint32, v uint64) (pageCount, live uint32, ok bool) {
	for slot := 0; slot < 2; slot++ {
		if m, valid := readMeta(image, int(ps), slot); valid && m.txid == v {
			return m.pageCount, m.livePages, true
		}
	}
	return 0, 0, false
}

// simAllocator is database d's page high-water and free-list length in the running process — the
// allocator state the next commit draws from — and where the free list's trailing run below the
// high-water starts (the high-water itself when its top page is not free; format.md *Trailing
// truncation*).
func (r *simRunner) simAllocator(d *simDB) (pageCount, free, trail uint32) {
	st, err := r.db.core.withStorage(d.name)
	if err != nil {
		return 0, 0, 0
	}
	st.mu.Lock()
	defer st.mu.Unlock()
	trail = st.pageCount
	for n := len(st.freePages); n > 0 && st.freePages[n-1] == trail-1; n-- {
		trail--
	}
	return st.pageCount, uint32(len(st.freePages)), trail
}

// observeGrowth starts a new bounded-growth lifetime for d (an open, a recovery, a compaction, an
// attach). The engine seeds its reclamation trigger with the page count minus the free list
// (format.md *Reclamation*), so a file whose dead pages are not all listed is reclaimed only after it
// doubles.
func (r *simRunner) observeGrowth(d *simDB) {
	pc, free, trail := r.simAllocator(d)
	d.high, d.free, d.trail, d.lacBound = pc, free, trail, pc-free
	d.last = simGrowth{}
}

// checkGrowth checks the reader-aware bounded-growth invariant after a commit published a new
// version of d (simulation-testing.md §8.3). With no reader pinned, no other process, and no fault,
// the engine reclaims in the commit once the pages off its free list pass compact_growth × the live
// count at its last reclamation (memory.md §8.4); readers legitimately hold reclamation back, so a
// commit with one open is not checked. A commit only adds pages off the list (each page it allocates
// leaves the list or grows the file), so the count it began with is a lower bound. Two checks follow:
//   - a quiet commit that began with more pages off the list than max(compact_min_pages,
//     compact_growth × an upper bound on that live count) must have reclaimed: every page below the
//     high-water is meta, live, free, or written by the commit itself (its manifest and free-list
//     pages);
//   - the next quiet commit reuses that free list before it grows the file.
func (r *simRunner) checkGrowth(i int, d *simDB, quiet bool) {
	if r.service {
		return
	}
	pc, live, ok := simMetaOf(r.image(d), r.pageSize, d.version)
	if !ok {
		return
	}
	_, free, trail := r.simAllocator(d)
	var written, top uint32
	for pg := range r.fs.files[d.file].pages {
		if pg >= 2 {
			written++
			top = max(top, uint32(pg)+1)
		}
	}
	// Trailing truncation (§8.3): a quiet commit passes the reuse gate, so its tree pages take the
	// lowest free pages, whatever of the old trailing run they leave is truncated, and every later page
	// comes from the high-water at the run's start. A commit inside a relaxed batch never lowers the
	// high-water (validated-cow.md §4), so it only grows it to what it wrote.
	if quiet && d.batchPending && pc != max(d.high, top) {
		r.fail(i, "trailing truncation: %s has %d pages after a commit inside a relaxed batch that wrote up to page %d, "+
			"from %d pages", d.name, pc, top, d.high)
		return
	}
	if quiet && !d.batchPending && pc != max(d.trail, top) {
		r.fail(i, "trailing truncation: %s has %d pages after a quiet commit that wrote up to page %d, "+
			"from %d pages whose free list's trailing run began at %d", d.name, pc, top, d.high, d.trail)
		return
	}
	if quiet && pc < d.high && r.relaxed {
		// The shrink waits for the batch's flush (validated-cow.md §4): checked when the engine next
		// holds nothing pending (checkShrunk).
		d.shrinkDue = true
	} else if quiet && pc < d.high {
		limit := (int64(pc) + int64(growthStep(pc, r.pageSize))) * int64(r.pageSize)
		if length := int64(len(r.fs.files[d.file].cache)); length > limit {
			r.fail(i, "trailing truncation: %s lowered its high-water to %d pages but its file is %d bytes (at most %d)",
				d.name, pc, length, limit)
			return
		}
	}
	before := d.last
	if d.batchOpen {
		// A commit inside a relaxed batch neither reuses nor frees the batch's pages (validated-cow.md
		// §4); only the bounds carry forward.
		d.high, d.free, d.trail = pc, free, trail
		d.lacBound = max(d.lacBound, live+written)
		d.last = simGrowth{}
		return
	}
	if quiet && before.reclaimed && pc > before.high && pc-before.high > written-min(written, before.free) {
		r.fail(i, "bounded growth: %s grew from %d to %d pages writing %d, with %d free pages to reuse",
			d.name, before.high, pc, written, before.free)
		return
	}
	reclaimed := false
	if quiet && d.high-d.free > max(compactMinPages, uint32(compactGrowth)*d.lacBound) {
		reclaimed = true
		if leaked := pc - 2 - live - free; pc < 2+live+free || leaked > written {
			r.fail(i, "bounded growth: %s has %d pages, %d live and %d free, after a commit that wrote %d "+
				"must have reclaimed every dead page", d.name, pc, live, free, written)
			return
		}
	}
	d.high, d.free, d.trail = pc, free, trail
	d.lacBound = max(d.lacBound, live+written)
	d.last = simGrowth{reclaimed: reclaimed, high: pc, free: free}
}

// checkTruncated checks trailing truncation against batched durability (§8.3, validated-cow.md §4).
// The file never shrinks below the durable floor's high-water: while a relaxed batch is pending the
// floor is the only generation recovery is sure to find, so a shrink before the flush must not cut its
// pages. And once the engine holds nothing pending again, a shrink that a relaxed commit deferred has
// happened: the file is at most one growth step past the published high-water.
func (r *simRunner) checkTruncated(i int, d *simDB) bool {
	f := r.fs.files[d.file]
	if f == nil {
		return true
	}
	length := int64(len(f.cache))
	if pc, _, ok := simMetaOf(f.cache, r.pageSize, d.floor); ok && int64(pc)*int64(r.pageSize) > length {
		r.fail(i, "trailing truncation: %s's file is %d bytes, shorter than its durable version %d's %d pages", d.name, length, d.floor, pc)
		return false
	}
	if !d.shrinkDue {
		return true
	}
	if r.fs.dead || r.fs.fired != "" || r.fs.fault != nil {
		d.shrinkDue = false // a crash or fault may have cut the flush short
		return true
	}
	if !r.engineFlushed(d) {
		return true
	}
	d.shrinkDue = false
	pc, _, ok := simMetaOf(f.cache, r.pageSize, d.version)
	if !ok {
		return true
	}
	if limit := (int64(pc) + int64(growthStep(pc, r.pageSize))) * int64(r.pageSize); length > limit {
		r.fail(i, "trailing truncation: %s flushed a batch that lowered its high-water to %d pages but its file is %d bytes (at most %d)",
			d.name, pc, length, limit)
		return false
	}
	return true
}

func (r *simRunner) stepEnd(i int, st simStep) {
	ss, ok := r.sessions[st.sid]
	if !ok {
		r.emit(`{"i":%d,"op":%q,"sid":%q,"skip":true}`, i, st.kind, st.sid)
		return
	}
	delete(r.sessions, st.sid)
	if st.kind == "rollback" {
		if err := ss.s.Rollback(); err != nil {
			r.emit(`{"i":%d,"op":"rollback","sid":%q,"error":%q}`, i, st.sid, simCode(err))
			return
		}
	} else {
		// Snapshot isolation: a reader still sees exactly the version of every database it pinned,
		// however many commits, reclamations, and page reuses happened since.
		lost := false
		if !ss.write {
			for _, d := range r.order() {
				pin, pinned := ss.pins[d.name]
				if !pinned {
					continue
				}
				dg, ok := r.digest(ss.s, d)
				if !ok && r.service && simCode(r.digestErr) == "08006" {
					// Under the page service a read transaction open across a change of its process's role
					// fails 08006 (spec/pageservice/README.md §6.5): it never sees other contents.
					lost = true
					break
				}
				if !ok || !d.history[pin][dg] {
					r.fail(i, "isolation: reader %s no longer sees version %d of %s", st.sid, pin, d.name)
					break
				}
			}
		}
		ss.s.Close()
		if lost {
			r.emit(`{"i":%d,"op":%q,"sid":%q,"lost":true}`, i, st.kind, st.sid)
			return
		}
	}
	r.emit(`{"i":%d,"op":%q,"sid":%q}`, i, st.kind, st.sid)
}

// stepCompact runs host compaction (api.md §2.6) of database name: the committed snapshot rewritten
// as a fresh image at the next version, through the simulated filesystem's temp file, rename, and
// directory barrier. Its contents are unchanged, so a crash may recover either version with the
// same digest.
func (r *simRunner) stepCompact(i int, name string, rekey int) {
	// A rekey (S12) is compaction under a new data key: the same version and contents rules.
	op := "compact"
	if rekey != 0 {
		op = "rekey"
	}
	d := r.dbs[name]
	if d == nil || r.dbVersion(d) == 0 {
		r.emit(`{"i":%d,"op":%q,"db":%q,"skip":true}`, i, op, name)
		return
	}
	base := d.version
	d.addHistory(base+1, d.lastDigest)
	d.maxAttempted = max(d.maxAttempted, base+1)
	var err error
	if rekey != 0 {
		r.keyChange = &[2]int{r.key, rekey}
		if err = r.db.Rekey(name, simKeys[rekey], Argon2Params{}); err == nil {
			r.key = rekey
		}
	} else {
		err = r.db.Compact(name)
	}
	now := r.dbVersion(d)
	dbField := ""
	if name != "main" {
		dbField = fmt.Sprintf(`,"db":%q`, name)
	}
	if err != nil {
		code := simCode(err)
		if strings.HasPrefix(code, "non-engine") {
			r.fail(i, "%s", code)
			return
		}
		r.emit(`{"i":%d,"op":%q%s,"error":%q}`, i, op, dbField, code)
		switch {
		case code == "XX001":
			r.fail(i, "corruption: %s reported XX001: %v", op, err)
		case now != base:
			r.fail(i, "a failed %s published version %d of %s (was %d)", op, now, name, base)
		}
		return
	}
	r.emit(`{"i":%d,"op":%q%s,"version":%d}`, i, op, dbField, now)
	if now != base+1 {
		r.fail(i, "%s moved %s from version %d to %d", op, name, base, now)
		return
	}
	if dg, ok := r.committedDigest(d); !ok || dg != d.lastDigest {
		r.fail(i, "%s changed the contents of %s", op, name)
		return
	}
	if err := r.checkLive(); err != nil {
		r.fail(i, "after %s: %v", op, err)
		return
	}
	d.version = now
	d.floor = now // the rename and the directory barrier completed
	r.observeGrowth(d)
}

// stepChangeKey is `change_key <n>` (S12, encrypted.md §5): main's credential changes to simulation key
// n. Only the key block is written, so no version or content moves.
func (r *simRunner) stepChangeKey(i, n int) {
	if !r.encrypted {
		r.emit(`{"i":%d,"op":"change_key","skip":true}`, i)
		return
	}
	base := r.dbVersion(r.main())
	r.keyChange = &[2]int{r.key, n}
	if err := r.db.ChangeCredential("main", simKeys[n], Argon2Params{}); err != nil {
		code := simCode(err)
		if strings.HasPrefix(code, "non-engine") {
			r.fail(i, "%s", code)
			return
		}
		r.emit(`{"i":%d,"op":"change_key","error":%q}`, i, code)
		if code == "XX001" {
			r.fail(i, "corruption: change_key reported XX001: %v", err)
		}
	} else {
		r.key = n
		r.emit(`{"i":%d,"op":"change_key","key":%d}`, i, n)
	}
	if r.dbVersion(r.main()) != base {
		r.fail(i, "a credential change published a version")
	}
}

// stepBackup is `backup page_identical|compacted [p<N>]` (spec/design/page-service.md §9): the process
// backs main up into a new file through the simulated filesystem, while every other session keeps its
// pins and its writer gate. A backup that fails leaves no destination. One that succeeds is checked at
// once, as a new process would open it: its version is the pinned snapshot's (page-identical) or the
// one after it (compacted), the snapshot is the newest committed generation, its contents are that
// generation's, and the integrity checker accepts the image. Its image hash makes the cores' backups
// byte-identical (§8.4).
func (r *simRunner) stepBackup(i int, st simStep) {
	d := r.main()
	r.backups++
	dest := fmt.Sprintf("%s.backup%d", d.file, r.backups)
	err := BackupForTesting(r.db, dest, st.mode == "page_identical")
	if err != nil {
		code := simCode(err)
		if strings.HasPrefix(code, "non-engine") {
			r.fail(i, "%s", code)
			return
		}
		r.emit(`{"i":%d,"op":"backup","form":%q,"error":%q}`, i, st.mode, code)
		switch {
		case code == "XX001":
			r.fail(i, "corruption: backup reported XX001: %v", err)
		case r.fs.files[dest] != nil:
			r.fail(i, "a failed backup left its destination")
		}
		return
	}
	f := r.fs.files[dest]
	if f == nil {
		r.fail(i, "a successful backup left no destination")
		return
	}
	image := append([]byte(nil), f.cache...)
	if r.imagePrefix != "" {
		_ = os.WriteFile(fmt.Sprintf("%s.step%d.backup.img", r.imagePrefix, i), image, 0o644)
	}
	e, err := loadEngine(image, r.env)
	if err != nil {
		r.fail(i, "the backup does not open: %v", err)
		return
	}
	v := e.committed.txid
	snapshot := v
	if st.mode == "compacted" {
		snapshot = v - 1
	}
	copyDB := databaseOver(sharedCoreFromEngine(e))
	defer copyDB.Close()
	rs := copyDB.ReadSession()
	dg, ok := r.digest(rs, d)
	rs.Close()
	switch {
	case !ok:
		r.fail(i, "the backup cannot be read: %v", r.digestErr)
		return
	case snapshot < d.version && (!d.ownerLost || snapshot < d.floor):
		// A dead owner's batch may be lost back to the floor (§8.2): a backup that promotes its
		// process, or reaches a new owner, may then copy any version from the floor up.
		r.fail(i, "the backup copied version %d, older than the committed %d", snapshot, d.version)
		return
	case !d.history[snapshot][dg]:
		r.fail(i, "the backup holds contents (digest %s) version %d never had", dg, snapshot)
		return
	}
	if d.ownerLost {
		// The backup's pin is the first look at main since its owner died: what it copied is now
		// the committed generation, as observe records for a session.
		d.version, d.lastDigest = snapshot, dg
		d.ownerLost = false
	}
	live, pages, free, err := simIntegrity(image, v, r.credential())
	if err != nil {
		r.fail(i, "backup integrity: %v", err)
		return
	}
	r.emit(`{"i":%d,"op":"backup","form":%q,"version":%d,"digest":%q,"live":%d,"pages":%d,"free":%d,"image":"%016x"}`,
		i, st.mode, v, dg, live, pages, free, simImageHash(image, pages, r.pageSize))
}

// stepAttach attaches file database name to the running process (S4), first creating its file
// through the simulated filesystem if it does not exist — create's temp file, sync, rename, and
// directory barrier, any of which a fault may interrupt. Already attached, it only reports.
func (r *simRunner) stepAttach(i int, name string) {
	// Attaching takes the writer gate. The generator never attaches while a writer is open; a trace
	// that does (a shrinking artifact) would wait forever on this one thread, so it is invalid.
	var writers []string
	for sid, ss := range r.sessions {
		if ss.write {
			writers = append(writers, sid)
		}
	}
	if len(writers) > 0 {
		sort.Strings(writers)
		r.fail(i, "attach %s while %s holds the writer gate", name, writers[0])
		return
	}
	d := r.dbs[name]
	if d != nil && r.dbVersion(d) != 0 && (!r.service || r.attachedInAll(name)) {
		r.emit(`{"i":%d,"op":"attach","db":%q,"version":%d}`, i, name, d.version)
		return
	}
	if d == nil {
		d = newSimDB(name, name+".jed")
		r.dbs[name] = d
	}
	if r.fs.files[d.file] == nil {
		// A fresh file is version 1, empty. Until create returns it may vanish in a crash (floor 0).
		d.history = map[uint64]map[string]bool{}
		d.addHistory(1, simEmptyDigest(d))
		d.version, d.lastDigest, d.floor, d.maxAttempted = 1, simEmptyDigest(d), 0, 1
		e, err := createVia(r.fs, d.file, databaseOptions{PageSize: r.pageSize, env: r.env})
		if err != nil {
			r.attachFailed(i, name, err)
			return
		}
		_ = e.Close()
		d.floor = 1 // create returned: the file and its directory entry are durable
	}
	if r.service {
		if !r.attachEverywhere(i, name) {
			return
		}
	} else if err := r.attach(name); err != nil {
		r.attachFailed(i, name, err)
		return
	}
	v := r.dbVersion(d)
	dg, ok := r.committedDigest(d)
	if !r.checkRecovered(i, d, v, dg, ok, "attached") {
		return
	}
	r.observeGrowth(d)
	r.emit(`{"i":%d,"op":"attach","db":%q,"version":%d}`, i, name, v)
}

// attachEverywhere attaches file database name in every running process of a service trace (README.md
// §6.6): main's owner first — so it owns the file too, and one process owns every database — then the
// others in process order, each a page client of it. With no owner of main, the lowest process's read
// begin first re-elects it. A process that already has it attached is skipped. It leaves the attaching
// owner as the step's process.
func (r *simRunner) attachEverywhere(i int, name string) bool {
	first := r.ownerPid()
	if first < 0 {
		first = r.livePids()[0]
		r.selectProc(first)
		dg, ok := r.committedDigest(r.main())
		if !r.observe(i, fmt.Sprintf("attaching p%d", first), r.db.Version(), dg, ok) {
			return false
		}
		r.net.settle()
	}
	order := []int{first}
	for _, pid := range r.livePids() {
		if pid != first {
			order = append(order, pid)
		}
	}
	for _, pid := range order {
		r.selectProc(pid)
		if r.db.core.attachment(name) != nil {
			continue
		}
		err := r.attach(name)
		r.net.settle()
		if err != nil {
			r.selectProc(first)
			r.attachFailed(i, name, err)
			return false
		}
	}
	r.selectProc(first)
	return true
}

// attachedInAll reports whether every running process has attachment name attached.
func (r *simRunner) attachedInAll(name string) bool {
	for _, pid := range r.livePids() {
		if r.procs[pid].db.core.attachment(name) == nil {
			return false
		}
	}
	return true
}

func (r *simRunner) attachFailed(i int, name string, err error) {
	code := simCode(err)
	if strings.HasPrefix(code, "non-engine") || code == "XX001" {
		r.fail(i, "attach %s: %v", name, err)
		return
	}
	r.emit(`{"i":%d,"op":"attach","db":%q,"error":%q}`, i, name, code)
}

// dbsJSON renders the attachments' check/recovery state as `,"dbs":{"a1":{...},...}`, or "" with
// none.
func simDbsJSON(entries []string) string {
	if len(entries) == 0 {
		return ""
	}
	return `,"dbs":{` + strings.Join(entries, ",") + `}`
}

func (r *simRunner) stepCheck(i int) {
	var entries []string
	var mainLine string
	for _, d := range r.order() {
		if r.service && d.name != "main" && r.dbVersion(d) == 0 {
			// This process is not attached to it: a faulted attach killed the process attaching it
			// before this one did; the next attach step repairs that.
			continue
		}
		v, dg, ok := r.committedView(d)
		switch {
		case r.service:
			// Another process may have died leaving a newer complete generation this one now adopts.
			if !r.observeDB(i, d, "check", v, dg, ok) {
				return
			}
		case !ok || v != d.version || dg != d.lastDigest:
			r.fail(i, "a read session does not see the last committed version of %s", d.name)
			return
		}
		image := r.image(d)
		live, pages, free, err := simIntegrity(image, d.version, r.credential())
		if err != nil {
			r.fail(i, "integrity of %s: %v", d.name, err)
			return
		}
		body := fmt.Sprintf(`"version":%d,"digest":%q,"live":%d,"pages":%d,"free":%d,"image":"%016x"`,
			d.version, dg, live, pages, free, simImageHash(image, pages, r.pageSize))
		if d.name == "main" {
			mainLine = body
		} else {
			entries = append(entries, fmt.Sprintf(`%q:{%s}`, d.name, body))
		}
	}
	if err := r.checkLive(); err != nil {
		r.fail(i, "live integrity: %v", err)
		return
	}
	r.emit(`{"i":%d,"op":"check",%s%s}`, i, mainLine, simDbsJSON(entries))
}

// closeFlushed raises each database's floor to its published version after every process closed
// cleanly under synchronous = off, when the close left every byte of the file and its directory entry
// durable: a clean close flushes the batch (validated-cow.md §4). A generation a recovered process
// adopted and never had to stabilize (it wrote nothing) may still be pending, and keeps its floor
// (§8.2). So does a database whose owner died: what it published may be gone until a process observes
// the database again.
func (r *simRunner) closeFlushed() {
	if !r.relaxed {
		return
	}
	for _, d := range r.order() {
		f := r.fs.files[d.file]
		if f != nil && len(f.pending) == 0 && r.fs.entryDurable(d.file) && !d.ownerLost && d.version > d.floor {
			d.floor = d.version
		}
	}
}

// stepReopen ends every session cleanly, closes the Database, and reopens it: the result must be
// exactly the last committed version of every database.
func (r *simRunner) stepReopen(i int) bool {
	for _, pid := range r.livePids() {
		if err := r.closeProc(pid); err != nil {
			r.fail(i, "close: %v", err)
			return false
		}
	}
	// Close flushed every batch, so a shrink a relaxed commit deferred has happened, and the floor the
	// file is held to is the version it flushed (validated-cow.md §4), not the one before it.
	r.closeFlushed()
	for _, d := range r.order() {
		if !r.checkTruncated(i, d) {
			return false
		}
	}
	r.fs.processDeath()
	if err := r.open(); err != nil {
		r.fail(i, "reopen failed: %v", err)
		return false
	}
	var entries []string
	var mainV uint64
	var mainD string
	for _, d := range r.order() {
		if r.dbVersion(d) == 0 && d.name != "main" && r.service && d.floor == 0 && r.fs.files[d.file] == nil {
			// A faulted attach killed its owner before create returned (S8 kills only the owner, so no
			// recovery ran to forget it): the file may legitimately be gone.
			delete(r.dbs, d.name)
			continue
		}
		if r.dbVersion(d) == 0 {
			r.fail(i, "a clean reopen lost attachment %s", d.name)
			return false
		}
		v := r.dbVersion(d)
		dg, ok := r.committedDigest(d)
		if r.service {
			// A process killed mid-commit may have left a complete generation no survivor began on yet.
			if !r.observeDB(i, d, "reopened p0", v, dg, ok) {
				return false
			}
		} else if v != d.version || !ok || dg != d.lastDigest {
			r.fail(i, "a clean reopen returned version %d of %s (digest %s), want version %d (digest %s)", v, d.name, dg, d.version, d.lastDigest)
			return false
		}
		r.observeGrowth(d)
		if d.name == "main" {
			mainV, mainD = v, dg
		} else {
			entries = append(entries, fmt.Sprintf(`%q:{"version":%d,"digest":%q}`, d.name, v, dg))
		}
	}
	r.emit(`{"i":%d,"op":"reopen","version":%d,"digest":%q%s}`, i, mainV, mainD, simDbsJSON(entries))
	return true
}

// checkRecovered checks a database's version and contents after a recovery or an attach against
// its history and durability floor (§8.1–8.2).
func (r *simRunner) checkRecovered(i int, d *simDB, v uint64, dg string, ok bool, what string) bool {
	switch {
	case !ok:
		r.fail(i, "%s: version %d of %s is unreadable: %v", what, v, d.name, r.digestErr)
	case v < d.floor:
		r.fail(i, "durability: %s version %d of %s, but version %d was durable", what, v, d.name, d.floor)
	case v > d.maxAttempted:
		r.fail(i, "%s: version %d of %s was never attempted (latest attempted %d)", what, v, d.name, d.maxAttempted)
	case !d.history[v][dg]:
		r.fail(i, "%s: version %d of %s has contents (digest %s) no transaction produced", what, v, d.name, dg)
	}
	if r.violation != "" {
		return false
	}
	d.version, d.lastDigest = v, dg
	return true
}

// recover abandons the crashed process — its sessions and Database — and opens the disk as a new
// process would, then checks every database's recovered generation against its history and
// durability floor (§8.1–8.2) and its image against the integrity checker (§8.3).
func (r *simRunner) recover(i int, fired string) bool {
	for _, pid := range r.livePids() {
		r.dropProc(pid)
	}
	r.fs.processDeath()
	images := map[string][]byte{}
	for _, d := range r.order() {
		images[d.name] = r.image(d)
		if d.name != "main" && images[d.name] == nil {
			// A crash during the attachment's create: allowed only while create had not returned.
			if d.floor > 0 {
				r.fail(i, "durability: attachment %s's file is gone, but version %d was durable", d.name, d.floor)
				return false
			}
			delete(r.dbs, d.name)
			continue
		}
		if r.imagePrefix != "" {
			suffix := ""
			if d.name != "main" {
				suffix = "." + d.name
			}
			_ = os.WriteFile(fmt.Sprintf("%s.step%d%s.img", r.imagePrefix, i, suffix), images[d.name], 0o644)
		}
	}
	if !r.settleKey(i, images["main"]) {
		r.crashImage = images["main"]
		return false
	}
	if err := r.open(); err != nil {
		r.crashImage = images["main"]
		r.fail(i, "recovery: open failed: %v", err)
		return false
	}
	var entries []string
	var mainLine string
	for _, d := range r.order() {
		v := r.dbVersion(d)
		dg, ok := r.committedDigest(d)
		if !r.checkRecovered(i, d, v, dg, ok, "recovered") {
			r.crashImage = images[d.name]
			return false
		}
		live, pages, free, err := simIntegrity(images[d.name], v, r.credential())
		if err != nil {
			r.crashImage = images[d.name]
			r.fail(i, "recovery integrity of %s: %v", d.name, err)
			return false
		}
		r.observeGrowth(d)
		body := fmt.Sprintf(`"recovered":%d,"digest":%q,"live":%d,"pages":%d,"free":%d,"image":"%016x"`,
			v, dg, live, pages, free, simImageHash(images[d.name], pages, r.pageSize))
		if d.name == "main" {
			mainLine = body
		} else {
			entries = append(entries, fmt.Sprintf(`%q:{%s}`, d.name, body))
		}
	}
	r.emit(`{"i":%d,"op":"crash","fired":%q,%s%s}`, i, fired, mainLine, simDbsJSON(entries))
	return true
}

// stepCorrupt is `corrupt flips=N [reseal=1]` (simulation-testing.md §6.3): every process ends
// cleanly; bits flip in durable body pages of the main database; a new process opens it and reads
// everything; then the bits are repaired and the database must reopen exactly as it was. Without
// reseal a flip breaks its page's CRC, so every outcome must be XX001 or the right rows — never
// wrong rows. With reseal the CRC is recomputed, so only the engine's structural checks stand in
// the way: any engine error, or any rows, is allowed, but never a panic or a non-engine error.
func (r *simRunner) stepCorrupt(i int, st simStep) bool {
	reseal := st.params["reseal"] == "1"
	for _, pid := range r.livePids() {
		if err := r.closeProc(pid); err != nil {
			r.fail(i, "close: %v", err)
			return false
		}
	}
	r.fs.processDeath()
	m := r.main()
	file := r.fs.main()
	pc, _, ok := simMetaOf(file.cache, r.pageSize, m.version)
	if !ok {
		r.fail(i, "corrupt: no meta holds version %d", m.version)
		return false
	}
	flips := file.corrupt(uint64(i), st.intParam("flips"), pc, reseal)
	outcome := func(err error) (string, bool) {
		code := simCode(err)
		switch {
		case strings.HasPrefix(code, "non-engine"):
			r.fail(i, "corrupt: %s", code)
			return "", false
		case code != "XX001" && !reseal:
			r.fail(i, "corrupt: a flipped checksum surfaced as %s, not XX001: %v", code, err)
			return "", false
		}
		return code, true
	}
	opened, read := "ok", "-"
	if err := r.openProc(0); err != nil {
		if opened, ok = outcome(err); !ok {
			return false
		}
	} else {
		read = "ok"
		v := r.db.Version()
		dg, ok := r.committedDigest(m)
		switch {
		case !ok:
			if read, ok = outcome(r.digestErr); !ok {
				return false
			}
		case reseal:
		case !m.history[v][dg] || v > m.version || (v < m.version && v+1 != m.version):
			// A flip in the newest generation's dirty pages fails its validation, and recovery falls
			// back to the previous generation (validated-cow.md §1), which is intact.
			r.fail(i, "corrupt: version %d read back with contents (digest %s) no transaction produced", v, dg)
			return false
		}
		r.dropProc(0)
	}
	file.repair(flips)
	if err := r.open(); err != nil {
		r.fail(i, "corrupt: reopen after repair failed: %v", err)
		return false
	}
	if v := r.db.Version(); v != m.version {
		r.fail(i, "corrupt: after repair version %d, want %d", v, m.version)
		return false
	}
	if dg, ok := r.committedDigest(m); !ok || dg != m.lastDigest {
		r.fail(i, "corrupt: after repair the contents differ")
		return false
	}
	r.emit(`{"i":%d,"op":"corrupt","flipped":%d,"open":%q,"read":%q}`, i, len(flips), opened, read)
	return true
}

// livePids lists the running processes in order.
func (r *simRunner) livePids() []int {
	pids := make([]int, 0, len(r.procs))
	for pid := range r.procs {
		pids = append(pids, pid)
	}
	sort.Ints(pids)
	return pids
}

// sessionsOf lists pid's open sessions in name order.
func (r *simRunner) sessionsOf(pid int) []string {
	var sids []string
	for sid, ss := range r.sessions {
		if ss.pid == pid {
			sids = append(sids, sid)
		}
	}
	sort.Strings(sids)
	return sids
}

// closeProc ends process pid cleanly: its sessions end (a writer rolls back) and its Database closes,
// releasing its locks.
func (r *simRunner) closeProc(pid int) error {
	for _, sid := range r.sessionsOf(pid) {
		if ss := r.sessions[sid]; ss.write {
			_ = ss.s.Rollback()
		} else {
			ss.s.Close()
		}
		delete(r.sessions, sid)
	}
	err := r.procs[pid].db.Close()
	if r.locks != nil {
		r.locks.release(pid)
	}
	delete(r.procs, pid)
	if r.service {
		r.net.kill(pid)
		r.net.settle()
	}
	return err
}

// dropProc abandons process pid as a crash does: its sessions and Database vanish without closing,
// and the kernel releases its locks.
func (r *simRunner) dropProc(pid int) {
	if p := r.procs[pid]; p != nil && p.db != nil {
		// A dead owner may take every version above the floor with it (§8.2): under synchronous = off
		// the simulated process crash may drop writes of the step that acknowledged a commit, and under
		// either mode a generation it adopted but never stabilized (validated-cow.md §3) may be dropped
		// by a failed stabilization sync. Each database it owned (main or an attachment under the
		// service) has its own floor.
		for _, d := range r.dbs {
			if c := simServiceCore(p.db, d); c != nil && c.pageOwner() != nil {
				d.ownerLost = true
			}
		}
	}
	for _, sid := range r.sessionsOf(pid) {
		delete(r.sessions, sid)
	}
	if r.locks != nil {
		r.locks.release(pid)
	}
	delete(r.procs, pid)
	if r.cur == pid {
		r.db = nil
	}
	if r.service {
		// The kernel closes a dead process's sockets.
		r.net.kill(pid)
		r.net.settle()
	}
}

// observe checks the version and contents a process sees of main when it begins (S5): in a shared
// trace another process may have committed — or died mid-commit, leaving a complete generation
// another process adopts — so the version may be newer than the last this runner saw, but never
// older, and its contents must be a generation the history records.
func (r *simRunner) observe(i int, who string, v uint64, dg string, ok bool) bool {
	return r.observeDB(i, r.main(), who, v, dg, ok)
}

// observeDB is observe for database d: under the page service every attachment is shared too.
func (r *simRunner) observeDB(i int, m *simDB, who string, v uint64, dg string, ok bool) bool {
	what := ""
	if m.name != "main" {
		what = " of " + m.name
	}
	switch {
	case !ok:
		r.fail(i, "%s: version %d%s is unreadable", who, v, what)
	case v < m.version && (!m.ownerLost || v < m.floor):
		r.fail(i, "%s sees version %d%s after version %d was published", who, v, what, m.version)
	case v > m.maxAttempted:
		r.fail(i, "%s sees version %d%s, which was never attempted (latest attempted %d)", who, v, what, m.maxAttempted)
	case !m.history[v][dg]:
		r.fail(i, "%s sees version %d%s with contents (digest %s) no transaction produced", who, v, what, dg)
	}
	if r.violation != "" {
		return false
	}
	m.version, m.lastDigest = v, dg
	m.ownerLost = false
	return true
}

// selectProc makes pid the process running the step.
func (r *simRunner) selectProc(pid int) bool {
	p := r.procs[pid]
	if p == nil {
		return false
	}
	r.cur, r.db = pid, p.db
	return true
}

// stepPid is the process a step runs in: a session's own, an explicit one, or the lowest running.
func (r *simRunner) stepPid(st simStep) (int, bool) {
	switch st.kind {
	case "open", "spawn", "exit", "kill":
		return st.pid, true
	case "backup":
		if st.pid >= 0 {
			return st.pid, true
		}
	case "on", "commit", "rollback", "close":
		if ss := r.sessions[st.sid]; ss != nil {
			return ss.pid, true
		}
		return 0, false
	}
	if pids := r.livePids(); len(pids) > 0 {
		return pids[0], true
	}
	return 0, false
}

// stepSpawn starts a process (S5) and checks what it sees.
func (r *simRunner) stepSpawn(i int, pid int) {
	if r.procs[pid] != nil {
		// The generator cannot know a fault killed the owner and that p0 restarted since.
		r.emit(`{"i":%d,"op":"spawn","pid":%d,"skip":true}`, i, pid)
		return
	}
	if err := r.openProc(pid); err != nil {
		code := simCode(err)
		if strings.HasPrefix(code, "non-engine") || code == "XX001" {
			r.fail(i, "spawn p%d: %v", pid, err)
			return
		}
		r.emit(`{"i":%d,"op":"spawn","pid":%d,"error":%q}`, i, pid, code)
		return
	}
	v := r.db.Version()
	dg, ok := r.committedDigest(r.main())
	if !r.observe(i, fmt.Sprintf("spawned p%d", pid), v, dg, ok) {
		return
	}
	versions := map[string]uint64{}
	for _, name := range r.attachedNames() {
		a := r.dbs[name]
		av := r.dbVersion(a)
		if av == 0 {
			continue
		}
		adg, aok := r.committedDigest(a)
		if !r.observeDB(i, a, fmt.Sprintf("spawned p%d", pid), r.dbVersion(a), adg, aok) {
			return
		}
		versions[name] = r.dbVersion(a)
	}
	r.emit(`{"i":%d,"op":"spawn","pid":%d,"version":%d%s}`, i, pid, v, r.versionsJSON(versions))
}

// simImageHash folds the logical image — the pages below the high-water — into FNV-1a 64 (§8.4).
// Preallocated tails past the high-water are host policy and excluded.
func simImageHash(image []byte, pages, pageSize uint32) uint64 {
	n := int(pages) * int(pageSize)
	if n > len(image) {
		n = len(image)
	}
	h := fnv.New64a()
	h.Write(image[:n])
	return h.Sum64()
}
